// Policy-wide modifiers are percentages of the UNMODIFIED policy base — never of
// a base that already includes the item surcharges.
const policyModifiersOn = (policyBase: number): number =>
  firstInsuranceSurchargeOn(policyBase);

const quoteFor = (items: Item[]): Result => {
  const policyBase = policyBaseOf(items);
  return {
    premium: premiumRoundedInMHPCOsFavour(
      policyBase + itemSurchargesOn(items) + policyModifiersOn(policyBase) + PROCESSING_FEE,
    ),
  };
};
